class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { scroll: 0, fq: {} };
    this._fq = [];
    this.setScroller = (el) => { this.scroller = el; this.hdrKick(); };
    this.onScroll = (e) => { this.setState({ scroll: e.currentTarget.scrollTop, hdrHide: false }); this.hdrKick(); };
  }
  rvVals() {
    const STATIC = false, R = [[0, 150, 0.0, "up", 0], [0, 190, 0.6, "up", 0], [0, 230, 2.0, "up", 0], [0, 338, 2.5, "up", 0], [0, 446, 3.0, "up", 0], [0, 554, 3.5, "up", 0], [0, 662, 4.0, "up", 0], [0, 700, 4.5, "up", 0]], v = {}, vs = this.state.scroll || 0, secs = this.sections || [{ top: 0, h: 1e6 }], LITE = (typeof document !== 'undefined' && document.documentElement.classList.contains('lite'));
    const clamp = t => Math.max(0, Math.min(1, t)), ease = t => 1 - Math.pow(1 - t, 3);
    R.forEach((a, n) => {
      if (STATIC || LITE) { v['rv' + n] = ''; return; }   // phones: no scroll animation (saves memory)
      const sec = secs[a[0]] || secs[0], y = a[1], k = a[2], kind = a[3], rel = vs - sec.top;
      const ye = Math.min(780, y + k * 26), L = Math.min(460, Math.max(150, 1024 - ye - 110));
      const e = ease(clamp((rel + 1024 - ye - 70) / L)), r = 1 - e;
      let ty = kind === 'card' ? r * 80 : r * 44, op = e, sc = kind === 'card' ? 0.95 + 0.05 * e : 1;
      if (a[4] && rel > 0) { const x = clamp(rel / 1024); ty += x * (150 + k * 70); op *= 1 - clamp((rel - 80) / 620); sc *= 1 - x * 0.05; }
      v['rv' + n] = 'opacity: ' + op.toFixed(3) + '; transform: translate(0px, ' + ty.toFixed(1) + 'px)' + (sc !== 1 ? ' scale(' + sc.toFixed(4) + ')' : '');
    });
    return v;
  }
  hdrVals() { return { menuW: 'opacity: 1; pointer-events: auto', logoW: 'opacity: 1', pillStyle: this.state.hdrHide ? 'opacity: 0; filter: blur(10px); transform: translateY(12px); pointer-events: none; transition: opacity 0.6s ease, filter 0.6s ease, transform 0.6s ease' : 'opacity: 1; filter: blur(0px); transform: translateY(0px); transition: opacity 0.4s ease, filter 0.4s ease, transform 0.4s ease', hdrStyle: this.state.hdrHide ? 'opacity: 0; filter: blur(14px); transform: translateY(-14px); visibility: hidden; transition: opacity 0.6s ease, filter 0.6s ease, transform 0.6s ease, visibility 0s linear 0.6s' : 'opacity: 1; filter: blur(0px); transform: translateY(0px); visibility: visible; transition: opacity 0.45s ease, filter 0.45s ease, transform 0.45s ease, visibility 0s' }; }
  hdrKick() { clearTimeout(this._hdrT); this._hdrT = setTimeout(() => this.setState({ hdrHide: true }), 3000); }
  renderVals() {
    const v = Object.assign(this.hdrVals(), this.rvVals(), { setScroller: this.setScroller, onScroll: this.onScroll }), open = this.state.fq || {};
    for (let i = 0; i < 6; i++) {
      const on = !!open[i];
      v['fqRef' + i] = (el) => { this._fq[i] = el; };
      v['fqTap' + i] = (e) => {
        if (e && e.preventDefault) e.preventDefault();
        const nx = Object.assign({}, this.state.fq || {}); nx[i] = !nx[i]; this.setState({ fq: nx });
        if (nx[i]) { const go = () => { const el = this._fq[i], sc = this.scroller; if (!el || !sc) return; const top = el.offsetTop - 96; if (top > sc.scrollTop + 300 || top < sc.scrollTop - 4) sc.scrollTo({ top: Math.max(0, top), behavior: 'smooth' }); }; setTimeout(go, 90); setTimeout(go, 620); }
      };
      v['fqExp' + i] = on ? 'true' : 'false';
      v['fqRow' + i] = 'grid-template-rows: ' + (on ? '1fr' : '0fr');
      v['fqIn' + i] = on ? 'opacity: 1; transform: translate3d(0px, 0px, 0px)' : 'opacity: 0; transform: translate3d(0px, -12px, 0px)';
      v['fqIco' + i] = on ? 'transform: rotate(45deg); background: #05E5AF; border: 1px solid #05E5AF' : 'transform: rotate(0deg); background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.25)';
      v['fqQ' + i] = on ? 'color: #05E5AF' : 'color: #ffffff';
    }
    return v;
  }
}
